using FluentValidation.TestHelper;
using WhatsBiz.Application.Features.Finance;
namespace WhatsBiz.Tests.Finance; public sealed class FinanceValidatorTests { private readonly PartyTransactionValidator validator = new(); [Fact] public void RejectsInvalidTransaction() { var x = new PartyTransactionInput("OTHER", Guid.Empty, "", 0, default, null, null); validator.TestValidate(x).ShouldHaveAnyValidationError(); } [Fact] public void AcceptsValidReceipt() { var x = new PartyTransactionInput("CUSTOMER", Guid.NewGuid(), "UPI", 500, DateTimeOffset.UtcNow, "UPI-1", "Receipt"); validator.TestValidate(x).ShouldNotHaveAnyValidationErrors(); } }
